  // String form: pi applies the theme AND persists it to settings.json.
  const result = ui.setTheme(chosen);
  if (result.success) {
    ui.notify(`Theme: ${chosen}`, "info");
  } else {
    ui.notify(`Failed to set theme ${chosen}: ${result.error ?? "unknown error"}`, "error");
  }
}
