Current script contents (from my own /tmp copy): RELEASE is hardcoded. New version:

```js
#!/usr/bin/env node
// Load-test all user extensions in exactly the same way pi's extension
// loader does: use the jiti (from the active release) with the same
// alias map as dist/core/extensions/loader.js (Node build).
//
// Usage: node pi-ext-loadtest.mjs [version]
//   version: e.g. "1.5.2" (default: `pi --version`, fallback: the latest
//            version directory under install/releases)
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { homedir } from "node:os";
import { createRequire } from "node:module";

const AGENT_DIR = process.env.PI_CODING_AGENT_DIR ?? join(homedir(), ".pi", "agent");
const releasesRoot = path.join(AGENT_DIR, "install", "releases");

function detectVersion(explicit) {
  if (explicit) return explicit;
  const out = spawnSync("pi", ["--version"], { encoding: "utf8" });
  const m = (out.stdout || "").match(/\d+\.\d+\.\d+/);
  if (m && fs.existsSync(path.join(releasesRoot, m[0]))) return m[0];
  // Fallback: the latest installed release directory
  const dirs = fs.readdirSync(releasesRoot).filter(d => /^\d+\.\d+\.\d+$/.test(d)).sort((a,b) => a.localeCompare(b, undefined, { numeric: true }));
  return dirs.at(-1);
}

