#!/usr/bin/env node
/**
 * pi-ext-loadtest — load-test all user extensions exactly like pi's
 * extension loader does: jiti (from the active release) with the same
 * alias map as dist/core/extensions/loader.js (Node build).
 *
 * Usage:  node pi-ext-loadtest.mjs [version]
 *   version: e.g. "1.5.2" (default: `pi --version`, falling back to the
 *   highest version directory under install/releases).
 *
 * Exits 0 only if every extension module evaluates and exports a function.
 */
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createRequire } from "node:module";

const AGENT_DIR = process.env.PI_CODING_AGENT_DIR ?? path.join(os.homedir(), ".pi", "agent");
const RELEASES = path.join(AGENT_DIR, "install", "releases");

function detectVersion(explicit) {
  if (explicit) return explicit;
  const out = spawnSync("pi", ["--version"], { encoding: "utf8" });
  const m = (out.stdout || "").match(/\d+\.\d+\.\d+/);
  if (m && fs.existsSync(path.join(RELEASES, m[0]))) return m[0];
  const dirs = fs
    .readdirSync(RELEASES)
    .filter((d) => /^\d+\.\d+\.\d+$/.test(d))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  return dirs.at(-1);
}

const VERSION = detectVersion(process.argv[2]);
const RELEASE_ROOT = path.join(RELEASES, VERSION, "node_modules", "@earendil-works");
const RELEASE = path.join(RELEASE_ROOT, "pi-coding-agent");
const loaderUrl = path.join(RELEASE, "dist/core/extensions/loader.js");
if (!fs.existsSync(loaderUrl)) {
  console.error(`no pi release ${VERSION} at ${RELEASE} — pass a version that exists in ${RELEASES}`);
  process.exit(2);
}
const require = createRequire(loaderUrl);
const { createJiti } = require("jiti");

// Same aliases as pi's Node-build loader (see dist/core/extensions/loader.js
// getAliases()); only the two packages user extensions import are needed.
const aliases = {
  "@earendil-works/pi-coding-agent": path.join(RELEASE, "dist/index.js"),
  "@earendil-works/pi-tui": path.join(RELEASE_ROOT, "pi-tui", "dist/index.js"),
};

const extDir = path.join(AGENT_DIR, "extensions");
const files = fs.readdirSync(extDir).filter((f) => /\.(ts|mts|js)$/.test(f));
let fail = 0;
console.log(`pi release: ${VERSION}`);
for (const f of files) {
  const p = path.join(extDir, f);
  try {
    const jiti = createJiti(loaderUrl, { moduleCache: false, alias: aliases });
    const mod = await jiti.import(p, { default: false });
    const factory = mod.default ?? mod;
    const ok = typeof factory === "function";
    console.log(`${ok ? "OK   " : "BAD  "} ${f} (default export: ${typeof factory})`);
    if (!ok) fail++;
  } catch (err) {
    console.log(`FAIL ${f}: ${String(err.message || err).split("\n").slice(0, 3).join(" | ")}`);
    fail++;
  }
}
console.log(fail === 0 ? "ALL LOADED" : `${fail} FAILED`);
process.exit(fail === 0 ? 0 : 1);

// Validate ~/.pi/agent/skills/pi-extension-upgrade-check/SKILL.md
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";

const SKILL_DIR = path.join(process.env.HOME, ".pi/agent/skills/pi-extension-upgrade-check");
const file = path.join(SKILL_DIR, "SKILL.md");
const text = fs.readFileSync(file, "utf8");

let fails = 0;
const check = (ok, label, extra = "") => {
  console.log(`${ok ? "PASS" : "FAIL"} ${label}${extra ? " — " + extra : ""}`);
  if (!ok) fails++;
};

// 1. Frontmatter structure
const m = text.match(/^---\n([\s\S]*?)\n---\n/);
check(!!m, "frontmatter block present");
let fm = {};
if (m) {
  const require = createRequire(path.join(process.env.HOME, ".pi/agent/install/releases/1.5.2/node_modules/@earendil-works/pi-coding-agent/dist/index.js"));
  const YAML = require("yaml");
  fm = YAML.parse(m[1]);
  check(true, "frontmatter parses as YAML");
} else {
  check(false, "frontmatter parses as YAML");
}

// 2. Field constraints (Agent Skills spec)
check(typeof fm.name === "string" && fm.name.length > 0 && fm.name.length <= 64, "name non-empty, <=64", fm.name);
check(/^[a-z0-9]+(-[a-z0-9]+)*$/.test(fm.name ?? ""), "name matches naming convention");
check(typeof fm.description === "string" && fm.description.length > 0 && fm.description.length <= 1024, "description non-empty, <=1024", `${fm.description?.length ?? 0} chars`);
check(fm.name === path.basename(SKILL_DIR), "name matches directory name");

// 3. Referenced paths exist
const home = process.env.HOME;
const refs = [
  ".pi/agent/extensions",
  ".pi/agent/install/releases",
  ".pi/agent/bin/pi-ext-loadtest.mjs",
  ".pi/agent/node_modules/@earendil-works",
  ".pi/agent/projects/themes/package.json",
];
for (const r of refs) check(fs.existsSync(path.join(home, r)), `path exists: ${r}`);

// 4. tsconfig template is valid JSON
const json = text.match(/```json\n([\s\S]*?)\n```/)?.[1];
try {
  JSON.parse(json ?? "{}");
  check(true, "embedded tsconfig template is valid JSON");
} catch (e) {
  check(false, "embedded tsconfig template is valid JSON", String(e).slice(0, 80));
}

// 5. Body non-trivial
check(text.length > 1500, "skill body has substance", `${text.length} chars total`);

console.log(fails === 0 ? "SKILL VALID" : `${fails} FAILURES`);
process.exit(fails === 0 ? 0 : 1);

